      "acaoCorretiva": "Remoção de Leira, Ajuste de Berma e Eliminação de Sump",
      "planoAcao": "Solicito a execução de serviços para adequação do acesso localizado na área indicada na imagem anexa, conforme coordenadas registradas (23K 594986 7778332, altitude 1223,4 m). A intervenção é necessária para garantir condições seguras e operacionais de tráfego, atendendo aos padrões de estabilidade e drenagem.\nEscopo da atividade:\n\nRemoção da leira de proteção existente na lateral do acesso, visando ampliar a faixa de circulação e eliminar pontos de restrição para execução de sondagem.\nAjuste da berma para garantir conformidade com o projeto e melhorar a estabilidade do talude adjacente.\nRemoção do sump presente no trecho, evitando acúmulo de água e possíveis processos erosivos que comprometem a integridade do acesso e da estrutura.\n\nJustificativa técnica:\nA configuração atual apresenta desníveis e obstruções que dificultam a circulação segura de equipamentos, além de favorecer o acúmulo de água em pontos críticos. A adequação proposta mitigará riscos operacionais, melhorará a drenagem e assegurará a conformidade com os requisitos geotécnicos e de segurança.\nSolicito programação da atividade com prioridade, considerando a necessidade de liberação do acesso para continuidade das operações de sondagem.",
