      "acaoCorretiva": "ADEQUAÇÃO DE DISPOSIÇÃO E DRENAGEM EM PILHA DE ESTÉRIL",
      "planoAcao": "Com o objetivo de reforçar as boas práticas geotécnicas e mitigar riscos operacionais associados às pilhas de estéril, enumero abaixo as diretrizes que devem ser rigorosamente observadas durante as atividades de disposição: Reforço as seguintes orientações operacionais para a disposição de pilhas de estéril: A drenagem superficial deve ser direcionada para o pé do talude, sendo vedado o lançamento de água sobre a face do talude. O direcionamento da drenagem para a face pode gerar erosão, perda de resistência do material e instabilidade dos taludes, com potencial evolução para rupturas, considerando o caráter drenante do material da pilha. Deve-se evitar a metodologia de disposição tipo “casca de ovo”, que favorece o empoçamento, dificulta a drenagem e aumenta o risco de instabilidade geotécnica. Outro ponto de atenção observado é a falta de marcação topográfica para execução das atividades. Essas medidas são essenciais para garantir a estabilidade das pilhas, a segurança operacional e a continuidade das operações.",
