      "planoAcao": "Durante inspeção geotécnica de rotina na estrutura PDE Jacó, foi constatado crescimento de vegetação rasteira e arbustiva ao longo do talude de jusante, bem como no entorno e interior dos sumps de drenagem da estrutura, conforme evidenciado nas imagens anexas.\n\nA condição observada compromete a adequada inspeção visual, dificulta a identificação precoce de possíveis anomalias geotécnicas (como erosões superficiais, surgências, trincas ou recalques) e pode impactar negativamente a eficiência do sistema de drenagem superficial, especialmente nos sumps, favorecendo assoreamento e obstruções.\n\nSolicitação:\nSolicita-se a execução de roçada mecanizada/manual, de forma controlada e técnica, contemplando:\n\nTalude de jusante da estrutura PDE Jacó, em toda sua extensão;\n\nÁrea dos sumps e seus acessos imediatos;\n\nPreservação da geometria original do talude, sem remoção de solo ou danos ao revestimento superficial;\n\nDestinação adequada do material vegetal removido.",
