      "planoAcao": "Durante inspeção de rotina na área da Pilha Mangaba, foi identificado descarte irregular de materiais diversos no interior do sump, conforme evidenciado na imagem registrada em campo.\n\nObservou-se a presença de resíduos como madeiras, sucatas, pallets e outros materiais, dispostos de forma inadequada dentro da estrutura de drenagem. Tal prática não está em conformidade com os procedimentos operacionais e ambientais, podendo ocasionar obstrução do sistema de drenagem, redução da eficiência do sump e potencial impacto ambiental, especialmente em eventos de chuva, quando pode ocorrer o carreamento desses resíduos para áreas externas.\n\nDiante do exposto, solicita-se a  limpeza imediata da área, com a remoção e destinação ambientalmente adequada dos materiais descartados, bem como reforço das orientações às equipes operacionais quanto à proibição de descarte de resíduos em estruturas de drenagem.\n\nLocal: Sump – Pilha Mangaba\nData do registro: 03/03/2026\nCoordenadas: 20°5'17,058\"S / 44°5'44,034\"W",
