      "planoAcao": "Durante inspeção geotécnica realizada nas proximidades do sump da Pilha Mangaba, foi identificada a presença de sumidouro/erosão localizada no solo, conforme evidenciado na imagem registrada em campo.\n\nObserva-se a formação de cavidades e abatimento do material superficial, indicando possível processo de erosão ou carreamento interno de finos. Essa condição pode favorecer a progressão do processo erosivo, comprometendo a estabilidade local do terreno e a eficiência do sistema de drenagem da área, especialmente durante eventos de precipitação.\n\nDiante do exposto, solicita-se a a avaliação e tratativa da área, contemplando a regularização do terreno, recomposição do material e compactação adequada, bem como a verificação das condições de drenagem superficial, a fim de evitar a evolução do processo erosivo.\n\nLocal: Proximidades do Sump – Pilha Mangaba\nData do registro: 03/03/2026\nCoordenadas: 20°5'18,276\"S / 44°5'41,646\"W",
