export const STATUS_COLORS = {
  'Realizado e Aprovado': '#17FF1F',
  'Não Realizado e Pendente': '#FBFF0E',
  'Não Realizado e Cancelado': '#7c8aa3',
  'Realizado e Reprovado': '#EE9835',
  'Chamados Vencidos': '#FF0000',
  'Sem classificação': '#5a6b85'
};

export const TIPO_COLOR = '#027bff';

export const CRIT_ORDER = ['A1', 'A2', 'A3', 'M1', 'M2', 'M3', 'B1', 'B2', 'B3', 'R1', 'R2', 'R3', 'N/D'];

export const CRIT_PRAZO = {
  A1: 7,
  A2: 14,
  A3: 21,
  M1: 30,
  M2: 60,
  M3: 90,
  B1: 30,
  B2: 60,
  B3: 120,
  R1: 7,
  R2: 15,
  R3: 30
};

export const getCritColor = (crit) => {
  if (!crit) return '#5a6b85';
  const c = String(crit).toUpperCase();
  if (c.startsWith('A')) return '#ff4b4b'; // Alto
  if (c.startsWith('M')) return '#ff9f1a'; // Médio
  if (c.startsWith('B')) return '#33d17a'; // Baixo
  if (c.startsWith('R')) return '#71d1f8'; // Risco
  return '#5a6b85';
};

export const getCritLabel = (crit) => {
  if (!crit) return 'N/D';
  const c = String(crit).toUpperCase();
  const prazo = CRIT_PRAZO[c];
  if (prazo) return `${c} · ≤${prazo}d`;
  return c;
};

export const MONTH_NAMES = [
  'Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun',
  'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'
];

export const formatMesLabel = (m) => {
  if (!m || !m.includes('-')) return m || '';
  const parts = m.split('-');
  const y = parts[0];
  const mo = parts[1];
  const idx = parseInt(mo, 10) - 1;
  return `${MONTH_NAMES[idx] || mo}/${y}`;
};

export const isTicketOpen = (t) => {
  return !['Realizado e Aprovado', 'Não Realizado e Cancelado'].includes(t.status);
};

export const getDaysTo = (dateStr) => {
  if (!dateStr) return null;
  const target = new Date(dateStr + 'T00:00:00');
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  return Math.floor((target - now) / (1000 * 60 * 60 * 24));
};

export const getEffectivenessBand = (ratio) => {
  if (ratio >= 0.80) return { color: '#17FF1F', label: 'ADEQUADO' };
  if (ratio >= 0.60) return { color: '#F9FF4A', label: 'ATENÇÃO' };
  return { color: '#FF0000', label: 'CRÍTICO' };
};

export const formatNumber = (num) => {
  if (num === null || num === undefined || isNaN(num)) return '0';
  return Number(num).toLocaleString('pt-BR');
};

/**
 * Calcula os indicadores executivos a partir de uma lista de tickets
 */
export const calculateChamadosStats = (tickets = []) => {
  const total = tickets.length;
  const aprovados = tickets.filter(t => t.status === 'Realizado e Aprovado').length;
  const cancelados = tickets.filter(t => t.status === 'Não Realizado e Cancelado').length;
  const pendentes = tickets.filter(t => t.status === 'Não Realizado e Pendente').length;
  const reprovados = tickets.filter(t => t.status === 'Realizado e Reprovado').length;
  const finalizados = tickets.filter(t => t.statusCh === 'Finalizado').length;
  
  const atingidos = aprovados + cancelados;
  const efetividade = total > 0 ? atingidos / total : 0;
  
  const abertos = tickets.filter(isTicketOpen);
  const vencidos = abertos.filter(t => t.limite && getDaysTo(t.limite) < 0).length;
  const aVencer7d = abertos.filter(t => {
    if (!t.limite) return false;
    const d = getDaysTo(t.limite);
    return d >= 0 && d <= 7;
  }).length;
  
  const georreferenciados = tickets.filter(t => t.lat && t.lon).length;
  
  return {
    total,
    aprovados,
    cancelados,
    pendentes,
    reprovados,
    finalizados,
    atingidos,
    efetividade,
    abertosCount: abertos.length,
    vencidos,
    aVencer7d,
    georreferenciados,
    band: getEffectivenessBand(efetividade)
  };
};
